import re, os, subprocess

root = '.'
# Collect all .c files under drivers/, net/
files = []
for top in ['drivers', 'net', 'kernel', 'fs', 'block', 'mm', 'ipc', 'security', 'lib']:
    for dirpath, dirnames, filenames in os.walk(top):
        for f in filenames:
            if f.endswith('.c'):
                files.append(os.path.join(dirpath, f))

# For each file: find napi poll functions (functions containing netif_napi_add references) and tasklet callbacks.
# Step 1: build map funcname -> (file, def_line) via simple regex of function definitions and registrations.

# Simpler approach: find functions that are registered as NAPI poll or tasklet callbacks, then check their bodies for plain spin_lock.

napi_poll_names = {}
tasklet_names = {}

reg_napi = re.compile(r'netif_napi_add(?:_weight|_tx)?\s*\(([^;]*?)\)\s*;')
reg_tasklet = re.compile(r'tasklet_(?:init|setup)\s*\(([^;]*?)\)\s*;')

for fp in files:
    try:
        text = open(fp, 'r', errors='replace').read()
    except Exception:
        continue
    lines = text.split('\n')
    for i, line in enumerate(lines):
        for m in reg_napi.finditer(line):
            args = m.group(1)
            # 3rd arg is the poll fn
            parts = [p.strip() for p in args.split(',')]
            if len(parts) >= 3:
                napi_poll_names[parts[2]] = (fp, i+1)
        for m in reg_tasklet.finditer(line):
            args = m.group(1)
            parts = [p.strip() for p in args.split(',')]
            if len(parts) >= 3:
                tasklet_names[parts[2]] = (fp, i+1)

print("napi poll fns:", len(napi_poll_names), "tasklet fns:", len(tasklet_names))

# Extract function bodies: find definition of name in file, then take up to matching braces.
def get_func_body(text, name):
    # match definition: name ( ... ) \n { ... } - handle return type on same line
    pat = re.compile(r'^[A-Za-z_][A-Za-z0-9_ \t\*]*\b' + re.escape(name) + r'\s*\(', re.M)
    for m in pat.finditer(text):
        start = m.start()
        # find opening brace after the closing paren of args
        depth = 0
        i = m.end() - 1
        while i < len(text):
            if text[i] == '(':
                depth += 1
            elif text[i] == ')':
                depth -= 1
                if depth == 0:
                    break
            i += 1
        # find {
        j = text.find('{', i)
        if j == -1:
            continue
        # match braces
        d = 0
        k = j
        while k < len(text):
            c = text[k]
            if c == '{':
                d += 1
            elif c == '}':
                d -= 1
                if d == 0:
                    break
            k += 1
        return text[start:k+1], text[:start].count('\n')+1
    return None, None

results = []
for name, (fp, regline) in list(napi_poll_names.items()) + list(tasklet_names.items()):
    try:
        text = open(fp, 'r', errors='replace').read()
    except Exception:
        continue
    body, defline = get_func_body(text, name)
    if body is None:
        continue
    # strip comments and strings roughly
    b = re.sub(r'/\*.*?\*/', '', body, flags=re.S)
    b = re.sub(r'//[^\n]*', '', b)
    # find plain spin_lock( acquisitions (not _bh/_irq/_irqsave/_nested/_try)
    locks = re.findall(r'spin_lock(?:_nested)?\s*\(&?([^),]+)\)?', b)
    locks = [l for l in locks if l.strip()]
    # check for bh disable presence
    has_bh = 'spin_lock_bh' in b or 'local_bh_disable' in b
    has_irq = re.search(r'spin_lock_irq|local_irq_(save|disable)', b)
    if locks and not has_bh and not has_irq:
        # also check callees within same file for lock acquisition: do a shallow pass
        results.append((name, fp, defline, regline, locks[:6]))

for r in results:
    print(r)
