import re, os, collections
root = '.'
# Collect all .c files under drivers/ and net/
files = []
for base in ['drivers', 'net', 'kernel', 'fs', 'mm', 'block']:
    for dp, dn, fn in os.walk(os.path.join(root, base)):
        for f in fn:
            if f.endswith('.c'):
                files.append(os.path.join(dp, f))
print("files scanned:", len(files))

# Find tasklet callback names: tasklet_init, tasklet_setup, DECLARE_TASKLET, and .func assignments
tasklet_names = set()
napi_names = set()
for fp in files:
    try:
        src = open(fp, errors='ignore').read()
    except Exception:
        continue
    for m in re.finditer(r'tasklet_init\s*\(\s*[^,]+,\s*([A-Za-z_][A-Za-z0-9_]*)\s*,', src):
        tasklet_names.add(m.group(1))
    for m in re.finditer(r'tasklet_setup\s*\(\s*[^,]+,\s*([A-Za-z_][A-Za-z0-9_]*)\s*\)', src):
        tasklet_names.add(m.group(1))
    for m in re.finditer(r'DECLARE_TASKLET[^ (]*\([^,]+,\s*([A-Za-z_][A-Za-z0-9_]*)\s*,', src):
        tasklet_names.add(m.group(1))
    for m in re.finditer(r'DECLARE_TASKLET_OLD\s*\(\s*[^,]+,\s*([A-Za-z_][A-Za-z0-9_]*)\s*\)', src):
        tasklet_names.add(m.group(1))
    for m in re.finditer(r'netif_napi_add(?:_weight|_ex)?\s*\(\s*[^,]+,\s*[^,]+,\s*([A-Za-z_][A-Za-z0-9_]*)', src):
        napi_names.add(m.group(1))
    # .poll = foo
    for m in re.finditer(r'\.poll\s*=\s*([A-Za-z_][A-Za-z0-9_]*)', src):
        napi_names.add(m.group(1))

print("tasklet cb names:", len(tasklet_names))
print("napi poll names:", len(napi_names))

# Now scan each file: extract function bodies of these names and check for plain spin_lock without bh
def find_bodies(src, names):
    out = {}
    for name in names:
        for m in re.finditer(r'^[A-Za-z_][A-Za-z0-9_ \t\*]*\b' + re.escape(name) + r'\s*\(', src, re.M):
            start = m.start()
            brace = src.find('{', m.end()-1)
            if brace == -1: continue
            depth = 0
            i = brace
            while i < len(src):
                if src[i] == '{': depth += 1
                elif src[i] == '}':
                    depth -= 1
                    if depth == 0:
                        break
                i += 1
            body = src[brace:i+1]
            out.setdefault(name, []).append((src.count('\n',0,start)+1, src.count('\n',0,i)+1, body))
            break
    return out

plain_lock_re = re.compile(r'spin_lock\s*\(')
bh_re = re.compile(r'spin_lock_bh|local_bh_disable|spin_lock_irqsave|spin_lock_irq\b')
hits = []
for fp in files:
    try:
        src = open(fp, errors='ignore').read()
    except Exception:
        continue
    bodies = find_bodies(src, tasklet_names | napi_names)
    for name, lst in bodies.items():
        for (ls, le, body) in lst:
            if plain_lock_re.search(body):
                hits.append((fp, name, ls, le))
print("\n=== tasklet/NAPI callbacks containing plain spin_lock ===")
for h in sorted(hits):
    print(h)
