import subprocess, re, sys, os

files = subprocess.run(['grep','-rln','netif_napi_add','--include=*.c','drivers/'], capture_output=True, text=True).stdout.split()
# focus on net/ethernet + wireless + staging + net/
files += [f for f in subprocess.run(['grep','-rln','netif_napi_add','--include=*.c','net/'], capture_output=True, text=True).stdout.split()]

res = []
for f in files:
    try: lines = open(f, errors='ignore').read().split('\n')
    except: continue
    # find poll fn names
    polls = set()
    for l in lines:
        for m in re.finditer(r'netif_napi_add(?:_tx|_weight)?\s*\([^;]*?,\s*([A-Za-z_0-9]+)\s*,', l):
            polls.add(m.group(1))
        for m in re.finditer(r'netif_napi_add(?:_tx|_weight)?\s*\(\s*[^,]+,\s*&?[A-Za-z_0-9>.]+\s*,\s*([A-Za-z_0-9]+)', l):
            polls.add(m.group(1))
    if not polls: continue
    # find each poll def
    for p in polls:
        for i,l in enumerate(lines):
            if re.search(r'\b'+re.escape(p)+r'\s*\(.*\)\s*$', l) or re.search(r'\b'+re.escape(p)+r'\s*\(', l) and '{' not in l and 'napi_add' not in l and not re.search(r'&\s*'+re.escape(p), l):
                # function start heuristics: line matches "static int p(..."
                if re.search(r'(static|int|void)\b.*\b'+re.escape(p)+r'\s*\(', l):
