                    for j in range(i, min(i+400, len(lines))):
                        if lines[j].startswith('}'):
                            end=j; break
                    body=lines[start:end+1]
                    plain=[start+k+1 for k,bl in enumerate(body) if re.search(r'spin_lock\s*\(', bl)]
                    if plain:
                        res.append((f,p,start+1,plain))
                    break
for r in res:
    print(r)
