import re, subprocess, collections

out = subprocess.run(['/usr/bin/rg','-l','tasklet_init\(|DECLARE_TASKLET','-g','*.c','drivers/','net/','sound/'],
                     capture_output=True, text=True).stdout.split()

pair = re.compile(r'spin_(lock|unlock)(?:_irqsave|_irqrestore|_irq|_bh|_nosync)?\s*\(\s*&?\s*([A-Za-z_][\w]*(?:\s*(?:->|\.)\s*[A-Za-z_]\w*)*)')
results = {}
for f in out:
    src = open(f, errors='ignore').read()
    exprs = {}
    for m in pair.finditer(src):
        line = src[:m.start()].count('\n') + 1
        kind, suffix = m.group(1), m.group(0).split('spin_'+kind)[1][:9]
        exprs.setdefault(m.group(2).replace(' ',''), []).append((line, m.group(0).rstrip('(').strip()))
    # group by base name of last member
    byname = collections.defaultdict(list)
    for e, lst in exprs.items():
        base = re.split(r'->|\.', e)[-1]
        byname[base].extend(lst)
    hits = []
    for base, lst in byname.items():
        suffixes = set(x[1] for x in lst)
        if len(suffixes) > 1:
            hits.append((base, sorted(set(x[1] for x in lst))))
    if hits:
        results[f] = hits

for f, h in sorted(results.items()):
    print("==", f)
    for base, sfx in h:
        print("   ", base, "->", sfx)
