		int sw_frame_id;
		sw_frame_id = (le32_to_cpu(
			np->tx_ring[entry].status) >> 2) & 0xff;
		if (sw_frame_id == hw_frame_id &&
			!(le32_to_cpu(np->tx_ring[entry].status)
			& 0x00010000))
